import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type * as React from "react";

/**
 * The Sistine material system — the single source of the material → markup mapping.
 *
 * FOUR materials (glass, frosted, crystal, opaque), each a `[data-material]` token set in
 * app/theme/materials.css, composed with orthogonal AXES (border, veil, size, gradient, glow, sheen)
 * over the one structural `glass` utility. Components call `glassMaterial()` instead of hardcoding
 * recipe class strings (check-theme bans the legacy `glass-bg`/`glass-surface`/… classes).
 *
 * Semantics:
 * - `material` UNDEFINED = adaptive: no attribute is rendered; the surface follows the page's
 *   [data-glass] style (the default everywhere).
 * - An explicit material PINS the element under any page style, and — because the token set is
 *   inherited custom properties — also acts as a scoped default for adaptive glass descendants
 *   (a dialog set to frosted re-skins the controls inside it; pin a child back with its own material).
 * - `"none"` = not a glass surface: the helper returns nothing and the component supplies its plain
 *   (shadcn) classes.
 */
export type Material = "glass" | "frosted" | "crystal" | "opaque" | "none";

export interface MaterialProps {
  /** undefined = adaptive (follows the page style); "none" = the component's plain fallback. */
  material?: Material;
  /** Material border. Three weights: `true`/"hairline" = the material's edge (1px; 0.5px under
   *  frosted), "rim" = 2px, "frame" = 4px. */
  border?: boolean | "hairline" | "rim" | "frame";
  /** Element-composed legibility floor for read-through overlays (menus, tooltips, toasts). */
  veil?: boolean;
  /** Blur/elevation tier — INTERNAL: set by a component's ROLE (glass-sm/-lg), not a public prop
   *  ("size" universally means a component's dimensions; the material tier must never shadow that). */
  size?: "sm" | "lg";
  /** Readability blur FLOOR (>= --glass-diffuse, default 12px) for text-dense translucent surfaces.
   *  Composes with any material; inert under opaque (nothing to blur through). */
  diffuse?: boolean;
  /** Brand-gradient accent layered over the material. */
  gradient?: boolean;
  /** Resting glow, or the intensified "lg" halo. */
  glow?: boolean | "lg";
  /** Opt-in hover shimmer (pseudo-element based — avoid on sticky/fixed surfaces). */
  sheen?: boolean;
}

/** The PUBLIC per-instance axis props a component spreads onto its type. Excludes `size` (the material
 *  blur tier is a role-internal detail — a component's own `size` prop owns that name). */
export type MaterialAxisProps = Omit<MaterialProps, "size">;

export interface MaterialAttrs {
  /** Spread-ready: undefined for adaptive and "none". */
  "data-material"?: Exclude<Material, "none">;
  /** "" when material === "none" (caller supplies its plain classes). */
  className: string;
}

export function glassMaterial(props: MaterialProps = {}): MaterialAttrs {
  const { material, border, veil, size, diffuse, gradient, glow, sheen } = props;
  if (material === "none") {
    return {
      className: "",
    };
  }
  return {
    "data-material": material,
    className: [
      "glass",
      border && "glass-border",
      border === "rim" && "glass-border-rim",
      border === "frame" && "glass-border-frame",
      veil && "glass-veil",
      size === "sm" && "glass-sm",
      size === "lg" && "glass-lg",
      diffuse && "glass-diffuse",
      gradient && "glass-gradient",
      glow === "lg" ? "glass-glow-lg" : glow ? "glass-glow" : false,
      sheen && "glass-sheen",
    ]
      .filter(Boolean)
      .join(" "),
  };
}

/**
 * The component-facing resolver: merge a component's ROLE (its default axes for a given semantic
 * variant) with explicit per-instance material/axis props, and return the surface markup — or null
 * when the element is NOT a glass surface (role === null, or material === "none").
 *
 * Explicit props override the role per-axis; unspecified axes fall back to the role.
 */
export function materialSurface(role: MaterialProps | null, props: MaterialProps): MaterialAttrs | null {
  if (props.material === "none" || role === null) {
    return null;
  }
  return glassMaterial({
    material: props.material,
    border: props.border ?? role.border,
    veil: props.veil ?? role.veil,
    size: props.size ?? role.size,
    diffuse: props.diffuse ?? role.diffuse,
    gradient: props.gradient ?? role.gradient,
    glow: props.glow ?? role.glow,
    sheen: props.sheen ?? role.sheen,
  });
}

/**
 * Typed per-element knobs → CSS custom properties ONLY (the cascade-native successor to the old
 * `glass={{…}}` inline-style prop). Everything routes through the token system, so nothing here can
 * fight a material, a page style, or the theme.
 *
 * The tint* keys recolor engine-composed tokens, which re-resolve at grouped declarations — pair
 * them with a `data-glass-tint` attribute on the same element so the engine re-composes there.
 */
export interface GlassVars {
  /** → --glass-tint-h (surface hue) */
  tintH?: number;
  /** → --glass-tint-c (surface chroma — the colorfulness master) */
  tintC?: number;
  /** → --glass-tint-a (tint film alpha) */
  tintA?: number;
  /** → --glass-opacity (0..1 solidify dial; element-composed in `glass`) */
  opacity?: number;
  /** → --srf-blur (number → px; glass material only) */
  blur?: number | string;
  /** → --glass-solid-a (veil floor alpha; element-composed in `glass-veil`) */
  solidA?: number;
}

export function glassVars(v: GlassVars = {}): React.CSSProperties {
  const s: Record<string, string> = {};
  if (v.tintH !== undefined) {
    s["--glass-tint-h"] = String(v.tintH);
  }
  if (v.tintC !== undefined) {
    s["--glass-tint-c"] = String(v.tintC);
  }
  if (v.tintA !== undefined) {
    s["--glass-tint-a"] = String(v.tintA);
  }
  if (v.opacity !== undefined) {
    s["--glass-opacity"] = String(v.opacity);
  }
  if (v.blur !== undefined) {
    s["--srf-blur"] = typeof v.blur === "number" ? `${v.blur}px` : v.blur;
  }
  if (v.solidA !== undefined) {
    s["--glass-solid-a"] = String(v.solidA);
  }
  return s as React.CSSProperties;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import { CaretDownIcon, CaretUpIcon, Check } from "@phosphor-icons/react";
import { cva, type VariantProps } from "class-variance-authority";
import { Select as SelectPrimitive } from "radix-ui";
import * as React from "react";

import { type MaterialAxisProps, materialSurface } from "@/lib/material";
import { cn } from "@/lib/utils";

/* Variant classes carry BEHAVIOR only; the surface comes from materialSurface. */
const selectTriggerVariants = cva(
  "flex w-full items-center justify-between whitespace-nowrap rounded-md border px-3 py-2 text-sm shadow-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50 data-[size=default]:h-9 data-[size=sm]:h-8 data-[placeholder]:text-muted-foreground [&>span]:line-clamp-1",
  {
    variants: {
      variant: {
        default: "border-input bg-background",
        glass: "",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

const selectContentVariants = cva(
  "relative z-50 max-h-96 min-w-[8rem] overflow-hidden rounded-xl shadow-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
  {
    variants: {
      variant: {
        default: "bg-popover text-popover-foreground border",
        glass: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

/* Trigger role: bordered adaptive glass. */
const TRIGGER_ROLE = {
  border: true,
};

/* Content role: bordered + veiled adaptive glass. */
const CONTENT_ROLE = {
  border: true,
  veil: true,
};

const Select = SelectPrimitive.Root;

const SelectGroup = SelectPrimitive.Group;

const SelectValue = SelectPrimitive.Value;

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> &
    VariantProps<typeof selectTriggerVariants> &
    MaterialAxisProps & {
      size?: "sm" | "default";
    }
>(({ className, children, variant = "glass", size = "default", material, border, veil, gradient, glow, sheen, diffuse, ...props }, ref) => {
  const m = materialSurface(variant === "default" ? null : TRIGGER_ROLE, {
    material,
    border,
    veil,
    gradient,
    glow,
    sheen,
    diffuse,
  });

  return (
    <SelectPrimitive.Trigger
      ref={ref}
      data-slot="select-trigger"
      data-size={size}
      data-material={m?.["data-material"]}
      className={cn(
        m?.className,
        selectTriggerVariants({
          variant,
        }),
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <CaretDownIcon className="h-4 w-4 opacity-50" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
});
SelectTrigger.displayName = SelectPrimitive.Trigger.displayName;

const SelectScrollUpButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollUpButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollUpButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollUpButton
    ref={ref}
    data-slot="select-scroll-up-button"
    className={cn("flex cursor-default items-center justify-center py-1", className)}
    {...props}
  >
    <CaretUpIcon className="h-4 w-4" />
  </SelectPrimitive.ScrollUpButton>
));
SelectScrollUpButton.displayName = SelectPrimitive.ScrollUpButton.displayName;

const SelectScrollDownButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollDownButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollDownButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollDownButton
    ref={ref}
    data-slot="select-scroll-down-button"
    className={cn("flex cursor-default items-center justify-center py-1", className)}
    {...props}
  >
    <CaretDownIcon className="h-4 w-4" />
  </SelectPrimitive.ScrollDownButton>
));
SelectScrollDownButton.displayName = SelectPrimitive.ScrollDownButton.displayName;

const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content> & VariantProps<typeof selectContentVariants> & MaterialAxisProps
>(
  (
    {
      className,
      children,
      position = "popper",
      align = "center",
      variant = "glass",
      material,
      border,
      veil,
      gradient,
      glow,
      sheen,
      diffuse,
      ...props
    },
    ref,
  ) => {
    const m = materialSurface(variant === "default" ? null : CONTENT_ROLE, {
      material,
      border,
      veil,
      gradient,
      glow,
      sheen,
      diffuse,
    });

    return (
      <SelectPrimitive.Portal>
        <SelectPrimitive.Content
          ref={ref}
          data-slot="select-content"
          data-material={m?.["data-material"]}
          className={cn(
            m?.className,
            selectContentVariants({
              variant,
            }),
            position === "popper" &&
              "data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1",
            className,
          )}
          position={position}
          align={align}
          {...props}
        >
          <SelectScrollUpButton />
          <SelectPrimitive.Viewport
            className={cn(
              "p-1",
              position === "popper" && "h-[var(--radix-select-trigger-height)] w-full min-w-[var(--radix-select-trigger-width)] scroll-my-1",
            )}
          >
            {children}
          </SelectPrimitive.Viewport>
          <SelectScrollDownButton />
        </SelectPrimitive.Content>
      </SelectPrimitive.Portal>
    );
  },
);
SelectContent.displayName = SelectPrimitive.Content.displayName;

const SelectLabel = React.forwardRef<React.ElementRef<typeof SelectPrimitive.Label>, React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>>(
  ({ className, ...props }, ref) => (
    <SelectPrimitive.Label ref={ref} data-slot="select-label" className={cn("px-2 py-1.5 text-sm font-semibold", className)} {...props} />
  ),
);
SelectLabel.displayName = SelectPrimitive.Label.displayName;

const SelectItem = React.forwardRef<React.ElementRef<typeof SelectPrimitive.Item>, React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>>(
  ({ className, children, ...props }, ref) => (
    <SelectPrimitive.Item
      ref={ref}
      data-slot="select-item"
      className={cn(
        "relative flex w-full cursor-default select-none items-center rounded-sm py-1.5 pl-2 pr-8 text-sm outline-none focus:bg-foreground/10 focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <span data-slot="select-item-indicator" className="absolute right-2 flex h-3.5 w-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="h-4 w-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  ),
);
SelectItem.displayName = SelectPrimitive.Item.displayName;

const SelectSeparator = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Separator ref={ref} data-slot="select-separator" className={cn("-mx-1 my-1 h-px bg-muted", className)} {...props} />
));
SelectSeparator.displayName = SelectPrimitive.Separator.displayName;

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};
